import type { ArticleCore } from "../types";

export const CORES_C: Record<string, ArticleCore> = {
  computing: {
    lede: `Computing is the art of making processes explicit enough that matter can carry them out. As a continent of this atlas it is not a museum of gadgets, nor a polite name for the industry that grew around silicon. It is a climate in which [[algorithms|algorithms]], [[information-theory|information]], and machines share one weather. The hub gathers [[computation-theory|the theory of computation]], [[cryptography|cryptography]], [[programming-languages|programming languages]], and [[artificial-intelligence|artificial intelligence]] because each asks what can be made mechanical without being made mindless. From [[lovelace|Ada Lovelace]] to the packet-switched [[internet|Internet]], the field keeps converting thought into procedure.`,
    idea: `A computation is a transformation that can be followed without insight, yet it is insight that invents the transformation. That paradox is the continent. [[Algorithms|Algorithms]] say how; [[complexity-classes|complexity classes]] say how much; [[computation-theory|the theory of computation]] says whether. [[Programming-languages|Programming languages]] are philosophies of what should be easy to utter, and [[compilers|compilers]] are the diplomats that make those philosophies executable. [[Databases|Databases]] remember; [[distributed-systems|distributed systems]] remember together while failing separately; [[cryptography|cryptography]] assumes that someone is listening. [[Machine-learning|Machine learning]] inverts the old bargain: instead of writing the rule, one writes a machine that finds a rule in examples. None of this is merely engineering. It is a branch of [[mathematics|mathematics]] that got its hands dirty, a branch of [[philosophy|philosophy]] that built instruments, and a branch of [[history|history]] that reorganized work, war, and attention. The atlas treats computing as a climate rather than a department, because the same questions leak into [[physics|physics]], [[biology|biology]], and [[mind|Mind]].`,
    lineage: `The lineage does not begin with a box of blinking lights. It begins with procedures that outlived their authors: Euclidean algorithms, astronomical tables, loom cards, and the dream that a calculus of reason might settle dispute. [[Lovelace|Ada Lovelace]] saw that a machine for number might weave patterns of thought. [[Turing|Alan Turing]] turned that vision into a mathematical object and then into a wartime instrument. [[Von-neumann|John von Neumann]] sketched the stored-program architecture that still ghosts inside ordinary machines. [[Shannon|Claude Shannon]] made communication a measurable resource, and [[Knuth|Donald Knuth]] made the analysis of algorithms a literature. The [[industrial-revolution|Industrial Revolution]] supplied engines; the [[world-wars|world wars]] supplied urgency; the [[cold-war|Cold War]] supplied funding and the [[internet|Internet]]. What looks like a sudden digital age is a long argument about symbol, mechanism, and control, now running on cheap silicon.`,
    tension: `The fault line is not whether machines will think. It is whether computing is a science of limits, a craft of systems, or a political economy of attention. Theorists pull toward [[logic|logic]] and undecidability; builders pull toward scale; firms pull toward capture. [[Artificial-intelligence|Artificial intelligence]] inherits all three pulls at once, and so do [[cryptography|cryptography]] and the [[internet|Internet]]. Another tension: the field speaks the language of neutrality — bits, protocols, abstractions — while rearranging power as thoroughly as any legal code. The atlas does not resolve this. It keeps [[ethics|ethics]] and [[political-philosophy|political philosophy]] in view so that a reader can feel the strain between what can be computed and what should be.`,
  },

  algorithms: {
    lede: `An algorithm is a finite procedure for transforming inputs into outputs, judged by correctness and by cost. It is older than computers and stricter than a recipe: each step must be definite, and termination is not a hope but a claim. In this atlas the topic sits between [[computation-theory|the theory of computation]] and the working arts of [[programming-languages|programming]] and [[machine-learning|machine learning]]. [[Knuth|Donald Knuth]] taught a generation to treat algorithms as literature; complexity theorists taught them to treat literature as a resource bound. To study algorithms is to ask not only whether a method works, but what it spends while working, and who can afford the bill.`,
    idea: `The idea is deceptively domestic. Sorting, searching, matching, routing, multiplying: these sound like chores, yet they are the load-bearing walls of every large system. An algorithm is a proof that a problem can be solved in a particular way, and the proof has a runtime. [[Graph-theory|Graph theory]] supplies the shapes; [[complexity-classes|complexity classes]] supply the ceilings; [[cryptography|cryptography]] supplies the adversaries who hope the ceilings hold. Correctness is not a vibe. It is an invariant that survives every legal input, including the ugly ones. Efficiency is not mere speed. It is a claim about how cost grows when the world grows, which is why an elegant cubic method can be a practical disaster. [[Machine-learning|Machine learning]] complicates the picture by replacing hand-built steps with fitted ones, but the fitted procedure is still an algorithm, only one whose authors cannot fully narrate it. The atlas keeps the topic close to [[natural-selection|natural selection]] and to [[proof|proof]], because search and guarantee are the two tempers of the field.`,
    lineage: `Named for the ninth-century mathematician al-Khwarizmi, the word traveled through Latin before it named a science. Euclid's method for greatest common divisors is already an algorithm in the modern sense: finite, definite, and indifferent to the scribe. Mechanical calculation, from astrolabes to Babbage, tried to house such procedures in brass. [[Lovelace|Ada Lovelace]] wrote what later readers would call a program. [[Turing|Alan Turing]] showed that a single machine could host every effective procedure, which made the study of algorithms a study of all of them at once. After 1945 the stored-program computer turned analysis into an urgent craft. Dijkstra, Hoare, and [[Knuth|Knuth]] made correctness and cost into public standards. The [[internet|Internet]] and [[databases|databases]] then demanded algorithms that survive failure, malice, and size, not merely a tidy worst-case bound on paper.`,
    tension: `The open quarrel is what should count as an explanation. A beautiful algorithm can be exhibited; a trained model can only be probed. Another quarrel: worst-case bounds versus typical-case behavior, which is the difference between a theorem and a Tuesday. [[Complexity-classes|Complexity classes]] organize the first; profiling and heuristics organize the second; they do not speak the same dialect. There is also a moral tension. Algorithms now allocate credit, attention, and suspicion, which means a faster method is not automatically a better civic act. The atlas leaves the reader between [[ethics|ethics]] and analysis, because a procedure that cannot be narrated is hard to accuse, and a procedure that can be narrated is hard to contain.`,
  },

  "artificial-intelligence": {
    lede: `Artificial intelligence is the project of building systems that perceive, model, and act in a world they did not invent. It is older than the phrase, which was coined to fund a summer, and younger than the dream of a mechanical mind. In the atlas it borders [[machine-learning|machine learning]], [[neural-networks|neural networks]], [[cognitive-psychology|cognitive psychology]], and [[language|language]], with [[turing|Alan Turing]] as a standing question rather than a mascot. The field is not one technique. It is a family of bets about what intelligence is, such that a machine could share it, fake it, or exceed it without ever quite possessing a life.`,
    idea: `The working idea keeps splitting. One lineage treats intelligence as the manipulation of symbols according to [[logic|logic]]; another treats it as the adjustment of weights in [[neural-networks|neural networks]]; a third treats it as the control of a body in a world, closer to [[mind|Mind]] than to chess. [[Machine-learning|Machine learning]] currently dominates because data became cheap and linear algebra became a superpower, but the older questions have not died. What would count as understanding rather than fluent imitation? What is a goal, and who sets it? How should a system handle the long tail of situations that no training set fairly samples? [[Turing|Turing]]'s imitation game made conversation a test; later researchers made games, proofs, perception, and protein shapes into tests. Each test quietly legislates a definition. The atlas files the topic next to [[decision-making|decision making]] and [[ethics|ethics]] because an agent is not only a predictor. It is a thing that changes the room it is in, including the human room.`,
    lineage: `Myths of living statues are not a research program. The modern field begins when computation becomes a public object: [[Turing|Turing]] in 1950, Dartmouth in 1956, then cycles of confidence and winter. Early programs searched trees and shuffled symbols; they were brittle in the open world. Expert systems bottled specialist lore and discovered that lore is expensive to maintain. Connectionists waited through scorn until data, chips, and backpropagation made [[neural-networks|neural networks]] industrial. The [[internet|Internet]] supplied both corpus and market. Meanwhile [[cognitive-psychology|cognitive psychology]] and neuroscience lent metaphors and sometimes constraints. What looks like a sudden revolution is a long oscillation between knowledge that is written and knowledge that is fitted, with [[von-neumann|von Neumann]] architectures hosting both, and with military and commercial patrons choosing which oscillation to fund.`,
    tension: `The live argument is not only safety versus capability, though that argument is real. It is whether the field is building tools, agents, or oracles, and which of those a society can bear. Fluency is easy to confuse with comprehension; scale is easy to confuse with generality; a benchmark is easy to confuse with a world. Another tension: the same systems that compress human culture also harvest it, which makes [[copyright|authorship]], labor, and [[political-philosophy|political philosophy]] interior to the technical problem. The atlas keeps [[consciousness|consciousness]] nearby as a temptation, not a trophy. A reader should leave this node able to distinguish a spectacular demo from a theory of mind, and a theory of mind from a license to deploy.`,
  },

  cryptography: {
    lede: `Cryptography is the mathematics of secrets, authenticity, and computation in the presence of enemies. It assumes that channels leak, participants cheat, and tomorrow's adversary has a better computer than today's designer. In the atlas it sits between [[prime-numbers|prime numbers]], [[information-theory|information theory]], [[algorithms|algorithms]], and the [[internet|Internet]], because a protocol is only as strong as the network it must survive. From handwritten ciphers to public-key proofs, the field converts mistrust into structure. It is one of the few sciences that becomes more interesting when people behave badly.`,
    idea: `The working idea is not mere concealment. Confidentiality, integrity, authenticity, and non-repudiation are different promises, and a system can keep one while burning the others. Classical ciphers hid messages; modern cryptography hides messages, identities, coins, and sometimes the fact that a computation occurred. [[Shannon|Shannon]] showed that perfect secrecy is possible and usually too expensive, which made computational hardness a resource. [[Complexity-classes|Complexity classes]] and number theory, especially the difficulty of factoring and of discrete logarithms, became walls. Public-key methods let strangers agree without a prior shared secret, which is why the [[internet|Internet]] can be both public and intimate. Proofs now travel with protocols: zero-knowledge, signatures, certificates. The adversary model is part of the theorem. If you change who can see what, or when, you have changed the problem. Cryptography is thus a branch of [[mathematics|mathematics]] that never forgets [[political-philosophy|politics]].`,
    lineage: `Substitution and transposition are ancient; so is the fantasy of an unbreakable script. Early modern Europe made ciphers into statecraft. The nineteenth century learned, slowly, that security through obscurity is a hobby. Shannon's wartime work and 1949 paper recast secrecy as a rate, linking the field to [[entropy|entropy]]. The 1970s detonated the subject: Diffie and Hellman published public key, RSA made primes into locks, and the argument between classified agencies and open researchers became a plot. [[Turing|Turing]]'s earlier work at Bletchley had already shown that a nation's fate could hang on a machine's patience. As the [[internet|Internet]] grew, cryptography left the embassy and entered the browser. Quantum algorithms now threaten some of the old walls, which is why [[quantum-computing|quantum computing]] is not a neighboring curiosity but a deadline.`,
    tension: `The standing fight is between cryptography as a right and cryptography as a weapon. States want doors; users want locks; vendors want both and a market. Export controls, key escrow, and lawful-access debates return in new jargon every decade. Another tension is scientific: security reductions assume hardness that is believed rather than proved, so the field lives on a mixture of theorems and nerves. Side channels — heat, time, cache, human error — mock the clean model. Post-quantum migration is a civil-engineering problem disguised as a math paper. The atlas keeps this node honest by placing it next to the [[cold-war|Cold War]] and [[ethics|ethics]], not only next to [[number-theory|number theory]].`,
  },

  "programming-languages": {
    lede: `A programming language is a notation for instructing machines, and also a philosophy of what should be easy to say. Syntax is the surface; semantics is the bet. In this atlas the topic lives beside [[compilers|compilers]], [[computation-theory|computation theory]], and [[lovelace|Ada Lovelace]], who saw that a machine for number might obey a pattern of thought. Each language makes some ideas cheap and others almost unsayable. To choose a language is to choose which mistakes will be easy, which proofs will be local, and which programmers will feel at home. The topic is therefore as much about minds as about machines.`,
    idea: `Languages are tools for managing complexity by lying at a controlled altitude. Assembly admits the machine; Fortran admits formulas; Lisp admits lists and the idea that code is data; types admit a conversation with a [[compilers|compiler]] before a program runs. A type system is a lightweight [[logic|logic]]; a memory model is a political constitution for bits; concurrency primitives are theories of time. [[Category-theory|Category theory]] and lambda calculus supply one deep dialect; objects, prototypes, and messages supply another. None is universal. The point of a language is not to express everything, but to make the frequent thing local and the dangerous thing loud. [[Knowledge-representation|Knowledge representation]] and this atlas itself depend on the same wager: that a well-chosen notation can turn a tangle into a path. When people fight about languages they are usually fighting about values — safety, speed, freedom, community — dressed as syntax.`,
    lineage: `The lineage begins before electricity. Ada Lovelace's notes on the Analytical Engine treat operations as composable thought. Fortran, in the 1950s, proved that a compiler could sell a language to scientists. Lisp, Algol, and COBOL split the culture into symbols, structures, and business records. The 1970s and 1980s produced C, Smalltalk, ML, and the long war between types and flexibility. Scripting languages rode the [[internet|Internet]]; managed runtimes tried to take memory away from the cowboy. Meanwhile the theory of programming languages borrowed from [[logic|logic]] and from [[mathematics|mathematics]], making reduction, types, and effects into theorems. [[Knuth|Knuth]]'s literate programming insisted that programs are for people first. The present is a pile of languages on one [[von-neumann|von Neumann]] metal, each a different treaty with that metal.`,
    tension: `The quarrel is whether languages should prevent harm or get out of the way. Safety and expressiveness trade; so do simplicity and completeness. A language that can say everything can hide everything, including the bug that ships. Another tension is social. Languages are communities, job markets, and identities; technical arguments become tribal ones with frightening speed. There is also a theoretical limit: no language can make all equivalent programs look equally clear, and [[godel|Gödel]] and [[turing|Turing]] still sit under the floorboards. The atlas files the topic near [[rhetoric|rhetoric]] as well as near machines, because a language is a way of persuading a future reader, including the compiler and one's future self.`,
  },

  "computation-theory": {
    lede: `The theory of computation asks what can be computed, how much it costs, and which questions no machine can settle. It is the geological layer under software, laid down by [[turing|Alan Turing]], Church, and the crisis in [[logic|logic]] that also produced [[godel|Kurt Gödel]]. In the atlas it neighbors [[algorithms|algorithms]], [[complexity-classes|complexity classes]], and [[proof|proof]]. The field is famous for negative results: undecidability, uncomputability, the things that remain out of reach no matter how fast the hardware becomes. Those limits are not a failure of engineering. They are discoveries about the shape of effective procedure itself.`,
    idea: `An effective procedure is a finite set of definite steps. Turing machines, lambda calculus, and recursive functions were shown to capture the same class, which is why Church's thesis is a thesis rather than a theorem: it identifies that class with what a human clerk, or a digital machine, can do in principle. Inside the computable lies the feasible, which is the subject of [[complexity-classes|complexity]]. Outside it lie problems that no algorithm can decide, including the halting problem and a wilderness of cousins. [[Logic|Logic]] supplies the language; diagonal arguments supply the bite. The theory also classifies models: automata, grammars, oracles, randomness, interaction. Each model is a different idea of a machine, and therefore a different idea of a mind. [[Artificial-intelligence|Artificial intelligence]] inherits the classification whether it admits it or not, because any claim that a system can solve a class of problems is a claim in this theory, even when it is made in a keynote.`,
    lineage: `Hilbert asked whether mathematics could be decided by a mechanical method. [[Godel|Gödel]] wrecked the hope that a rich formal system could prove all its truths from inside. [[Turing|Turing]], in 1936, gave the wreckage a machine and showed that the Entscheidungsproblem was unsolvable. Church arrived by another road. After the war, automata theory, formal languages, and then complexity theory turned the infinite into a practical map: what a compiler can parse, what a cryptographer can hope to hide, what a scheduler can guarantee. Cook, Karp, and Levin made NP-completeness a common tongue. The field kept borrowing from [[mathematics|mathematics]] while feeding [[programming-languages|programming languages]] and [[cryptography|cryptography]]. It is a lineage of limits that somehow produced an industry of possibilities.`,
    tension: `The standing discomfort is the gap between in-principle computation and in-practice computation. Undecidability is clean; feasibility is muddy, and P versus NP remains the unsolved hinge. Another discomfort is philosophical. If minds are machines, the limits apply to us; if they are not, the theory is silent about the thing we care for most. [[Quantum-computing|Quantum computing]] perturbs the map without erasing it, offering new cost landscapes rather than miracles. The atlas keeps this node close to [[epistemology|epistemology]] because a proof that a question cannot be settled is a kind of knowledge, and a culture that only funds speed will treat that knowledge as an insult.`,
  },

  "information-theory": {
    lede: `Information theory is [[shannon|Claude Shannon]]'s science of communication: bits, noise, and the price of reliability. It taught engineers that a message is not its meaning but a reduction of uncertainty, measurable against a set of possible messages. In the atlas it binds [[entropy|entropy]], [[cryptography|cryptography]], [[dna|DNA]], and the [[internet|Internet]], because channels are everywhere once you know how to see them. The theory is austere. It does not care what the message is about. It cares how much room it occupies, how much noise it can survive, and how close a code can come to the limit that mathematics allows.`,
    idea: `The bit is a unit of choice. Shannon entropy measures how surprising, on average, a source is; mutual information measures how much one variable tells you about another; channel capacity is the highest rate at which that telling can be reliable. Source coding compresses redundancy; channel coding spends redundancy on purpose as armor against noise. The two theorems that made the field are almost rude in their power: you can compress down to the entropy, and you can communicate at any rate below capacity with error driven arbitrarily close to zero. Meaning is postponed. That postponement is the method. It lets the same mathematics describe a telephone, a hard disk, a radio, a genome, and a rumor. [[Entropy|Entropy]] in [[physics|physics]] is a cousin, not an identity, and the family quarrel is itself a subject. [[Cryptography|Cryptography]] uses the theory to ask when a ciphertext still leaks; [[biology|biology]] uses it to ask what a sequence carries; this atlas uses it whenever a map pretends to be the territory.`,
    lineage: `Nyquist and Hartley had pieces of the puzzle. Shannon, at Bell Labs, assembled them in 1948 with a paper that read like a new physics of signals. War had made noisy channels a matter of survival; peace made them a matter of markets. Hamming and others built codes you could hold in your hand. Later came Kolmogorov complexity, which relocates information from ensembles to individual strings, and the long conversation with statistical mechanics. [[Maxwell|Maxwell]]'s demon, Szilard's engine, and Landauer's principle tied bits to heat. The [[internet|Internet]] is, among other things, an engineering monument to packets, checksums, and good-enough channels. [[Dna|DNA]] invited the metaphor of a text, which is sometimes a discovery and sometimes a temptation. The lineage is a century of learning to count what had seemed like quality.`,
    tension: `The theory's strength is its indifference to meaning; that is also its scandal. A perfectly compressed stream of propaganda and a perfectly compressed proof look alike to the bit counter. Another tension: Shannon entropy needs a probability model, and the world does not hand you one. Choose the wrong ensemble and you have measured a fantasy. There is also a cultural leak. People say "information" when they mean knowledge, news, or control, which is how a technical word becomes a fog. The atlas keeps [[epistemology|epistemology]] and [[semantics|language]] nearby so a reader can feel the gap between a channel and a mind, and between a bit and a reason.`,
  },

  turing: {
    lede: `Alan Turing (1912–1954) founded computer science as a branch of [[mathematics|mathematics]], then as a wartime craft, then as a question about minds. He did not merely imagine a machine. He defined the class of things a machine could do, and thereby the class of things it could not. In this atlas he stands at the junction of [[computation-theory|computation theory]], [[artificial-intelligence|artificial intelligence]], and [[cryptography|cryptography]]. The imitation game that bears his name is less a test than a dare: if conversation can be staged, what remains of the inner light. His life was cut short by a state that needed his work and punished his love.`,
    idea: `The Turing machine is a thought as severe as a monk's cell: a tape, a head, a finite table of habits. From that poverty he obtained universality, the halting problem, and a precise version of Hilbert's Entscheidungsproblem. The same mind designed practical machines, including work that helped break naval Enigma, and later turned to morphogenesis, as if biology were another computation waiting for equations. The 1950 paper on intelligence refused mysticism without refusing mystery: he replaced "Can machines think?" with a game that a skeptic might lose. [[Godel|Gödel]] had shown that formal systems leak truths; Turing showed that mechanical procedures leak unsolvable questions. Together they drew a border around what proof and calculation can claim. [[Artificial-intelligence|Artificial intelligence]] still camps on that border, sometimes pretending it is a highway.`,
    lineage: `Born in London, educated at Sherborne and King's College, Cambridge, Turing wrote the 1936 paper as a young logician and then crossed to Princeton, where Church's shadow was already long. The war pulled him into Bletchley Park, into bombe machines, into secrecy that would distort his public legend for decades. Afterward he worked on the ACE, on early programming, on chess, and on the chemical basis of form. Britain criminalized his sexuality, subjected him to chemical punishment, and lost him in 1954. A later pardon cannot restore the years. The atlas places him among [[lovelace|Lovelace]] and [[von-neumann|von Neumann]] not as a trinity of founders but as three different answers to the same temptation: to make thought run on matter. His afterlife is a mixture of saint, martyr, and brand.`,
    tension: `The arguments that follow him are not only about credit. They are about what his limits mean for minds. If human thought exceeds Turing computation, the excess needs a place to live — physics, embodiment, or myth. If it does not, then [[consciousness|consciousness]] becomes a pattern rather than a substance, which some find a liberation and others a theft. There is also a civic afterlife: a gay mathematician used as a national emblem by institutions that would have destroyed him again. Readers should keep the technical work and the cruelty in one frame. The atlas refuses to file him only under genius. Genius is a way of not seeing the police.`,
  },

  shannon: {
    lede: `Claude Shannon (1916–2001) made information measurable and communication a branch of [[mathematics|mathematics]]. Before him, engineers spoke of signals as one speaks of weather: qualitatively, with lore. After him they had a unit, the bit, and theorems that said how far a channel could be pushed before noise won. In the atlas he is the figure for [[information-theory|information theory]], with edges into [[entropy|entropy]], [[cryptography|cryptography]], and the [[internet|Internet]]. He was also a tinkerer of unicycling and juggling machines, a reminder that a severe theory can come from a playful hand.`,
    idea: `Shannon's master's thesis showed that Boolean algebra could design switching circuits, which is a founding document of digital design. His 1948 theory of communication then separated source from channel, message from meaning, and gave each a number. Entropy, in his sense, is expected surprise. Capacity is a speed limit with a proof. The noisy-channel coding theorem is one of the century's great permissions: spend redundancy wisely and you may send almost-perfect messages through an imperfect world. In cryptography he proved that a one-time pad, used honestly, leaks nothing, and that anything shorter is a compromise. The work is abstract enough to travel. Packets, disks, mobile phones, and genomic codecs all live in a landscape he drew without having seen them. He treated a message as a choice among possibles, which is why the theory can describe a telephone call and a coin flip with the same calm.`,
    lineage: `Raised in Michigan, Shannon worked with Vannevar Bush's differential analyzer at MIT, then at Bell Labs, where the telephone system was both patron and specimen. War research on fire control and secrecy sharpened the questions. The 1948 paper and the 1949 secrecy paper landed like a climate change in several fields at once. Later he wrote on chess programming, on juggling, on the stock market, and on a mechanical mouse that learned a maze. He did not found a school so much as a vocabulary. [[Wiener|Norbert Wiener]]'s [[cybernetics|cybernetics]] ran in parallel, more imperial in its claims about organisms and society; Shannon stayed closer to the channel. The [[internet|Internet]] is among other things a Shannon engine running at planetary scale, even when its designers were thinking about routing rather than entropy.`,
    tension: `Shannon warned that his theory was not a theory of meaning, and then watched the word information colonize culture anyway. That is the first afterlife argument: whether a bit is a humble unit or a metaphysics. The second is political. A science of channels becomes a science of surveillance, compression, and control as soon as institutions notice it. [[Cryptography|Cryptography]] and advertising both drink from the same well. A third argument is scientific: how Shannon entropy relates to thermodynamic [[entropy|entropy]] remains a place where physicists, computer scientists, and philosophers talk past one another. The atlas keeps him next to [[physics|physics]] and [[mind|Mind]] so the bit does not pretend to be the whole of a thought.`,
  },

  "von-neumann": {
    lede: `John von Neumann (1903–1957) was a polymath of computers, games, and self-reproducing automata, and a statesman of the early nuclear age. He could move from set theory to shock waves to poker without changing the temperature of his mind. In this atlas he binds [[computing|computing]] to [[game-theory|game theory]] and to [[self-organization|self-organization]], a reminder that architecture is a philosophical act. The stored-program idea associated with his name is less a single invention than a crystallization: instructions and data as the same kind of stuff, sitting in the same memory, waiting to be rewritten.`,
    idea: `The EDVAC report sketched a machine whose program lived in addressable memory, which made software a thing that could be modified by software. That move is the original sin and gift of modern computing. Von Neumann also wrote on cellular automata and self-reproduction, asking how an organized pattern could copy its organization, a question that still hums under [[biology|biology]] and [[artificial-intelligence|artificial intelligence]]. In [[game-theory|game theory]], with Morgenstern, he formalized strategic interdependence, giving economics and later the [[cold-war|Cold War]] a language of minimax and mixed strategies. He contributed to the mathematics of quantum mechanics, to operator algebras, to numerical weather, to the hydrogen bomb. The unity is not a topic. It is a style: find the invariant, write it so a machine or an institution could use it, accept the political weather that follows. [[Algorithms|Algorithms]] in his world were not only for sorting. They were for surviving.`,
    lineage: `Born in Budapest into a banking family, a child prodigy in a city that produced them like a crop, he passed through Berlin and Zurich into Princeton and the Institute for Advanced Study. He was in the room for the foundations crisis, for the Manhattan Project, for the first electronic computers, for the early RAND world of deterrence. The IAS machine, MANIAC, and the reports that trailed him seeded laboratories on several continents. He died of cancer in 1957, still working, still advising, still a figure around whom legends of speed accumulated. The atlas places him near [[turing|Turing]] and [[shannon|Shannon]] as a different kind of founder: less the hermit of a single theorem, more the person who could translate a theorem into an institution before lunch.`,
    tension: `The afterlife is morally loud. Von Neumann's fingerprints are on computing and on thermonuclear strategy, and the two are not easily unzipped. Admirers see a mind that served civilization by seeing clearly; critics see a mind that served power by making annihilation thinkable. Game theory's coolness can launder cruelty as equilibrium. The stored-program computer can launder labor as code. Readers should resist both hagiography and cartoon villainy. The tension worth keeping is structural: a mathematics of control will be used by whoever can fund it. The atlas keeps [[ethics|ethics]] and the [[world-wars|world wars]] adjacent so that architecture never looks like destiny.`,
  },

  lovelace: {
    lede: `Ada Lovelace (1815–1852) was the first to see that a machine for number might also weave patterns of thought. Daughter of Byron and of a mathematician determined to suppress poetry with sums, she wrote notes on Babbage's Analytical Engine that outran the engine, which was never built. In this atlas she stands at the door of [[programming-languages|programming languages]] and [[algorithms|algorithms]], a nineteenth-century witness to a twenty-first-century climate. Her fame has been contested, inflated, and recovered. The work that matters is still on the page: a method, a table, and a speculation about what symbols could become.`,
    idea: `Note G, on computing Bernoulli numbers, is the exhibit most often called the first computer program: a sequence of operations, loops, and working variables written for a machine of cogs. More lasting is the surrounding claim that the Engine might manipulate any symbols whose relations were definite, not only quantities — that it might compose music if music could be so rendered. That is the leap from calculator to computer, made before electricity. She also warned, against a certain intoxication, that the machine can do only what we know how to order it to perform, a sentence that [[artificial-intelligence|artificial intelligence]] still trips over. The notes are a collaboration with Babbage and a divergence from him. He wanted a perfect mill for numbers. She wanted a mill for thoughts, and she wanted its limits named. [[Computing|Computing]] as a continent begins, in one telling, with that double vision.`,
    lineage: `Augusta Ada Byron was educated in mathematics under a mother's anxious discipline, later corresponding with De Morgan and moving in a London of scientists and salons. Babbage's Difference Engine was a public spectacle of unfinished genius; the Analytical Engine, more ambitious, remained a paper creature with a few parts. Lovelace translated Menabrea's account and annotated it into a work twice as long, published in 1843. She died young of cancer, her gambling and her health already a mess. For a century she was a footnote; late twentieth-century computing, hungry for ancestors, made her a symbol, sometimes at the expense of precision. The atlas prefers the notes to the symbol. They belong with the [[industrial-revolution|Industrial Revolution]]'s other attempts to automate skill, and with a history of women whose technical work was filed under helpmeet.`,
    tension: `The argument about Lovelace is an argument about what counts as invention. Did she write a program, or a commentary? Did she see general-purpose computing, or have that vision read back into her? Both extremes are lazy. The notes are real; the Engine's absence is real; the later industry's need for a founding heroine is also real. A better tension is the one she named: the difference between a machine that follows orders and a mind that originates them. If that difference collapses, she is a prophet. If it stands, she is a lucid engineer of a limit. The atlas leaves both readings clickable, beside [[turing|Turing]]'s later, more formal, version of the same unease.`,
  },

  knuth: {
    lede: `Donald Knuth (born 1938) made the analysis of [[algorithms|algorithms]] into a literature, and then invented a literature for programs. The Art of Computer Programming is not a manual. It is a cathedral of methods, written as if algorithms deserved the same care as verses. In the atlas he stands with [[programming-languages|programming languages]] and [[proof|proof]], a high priest of exact cost and of the joke hidden in a recurrence. He also built TeX because he could not bear ugly books, which is a research program disguised as typesetting. Few living figures so clearly treat computing as a humane art.`,
    idea: `Knuth's distinctive claim is that an algorithm is not understood until its cost is understood, not as a slogan but as a function of input size, with leading constants and with the average case taken seriously. He gave the field MIX, later MMIX, so that analyses could share a machine. He popularized big-O conversation while insisting that O-notation without constants can be a way of not seeing. Literate programming, his later gospel, says that programs should be written as explanations from which code is derived, not as code from which explanations are reverse-engineered. TeX and METAFONT are existence proofs that a program can be a book and a tool at once. Underneath is a temperament: playfulness yoked to rigor, puzzles yoked to [[mathematics|mathematics]], an almost medieval faith that the right name and the right analysis will still matter when machines have changed their skins.`,
    lineage: `Raised in Milwaukee, Knuth found computers at Case and a calling at Caltech and Stanford. The Art began in the 1960s as an attempt to survey a young field and became a life, volumes appearing across decades like geological strata. He interrupted himself to build TeX when phototypesetting betrayed his galleys, and in doing so standardized how the sciences write. Awards accumulated; so did the sense of a figure both central and slightly aside from fashion — not a startup prophet, not an [[artificial-intelligence|AI]] impresario, a scholar of the discrete. The atlas places him downstream of [[turing|Turing]] and [[lovelace|Lovelace]], where craft becomes canon. His check-offering for errors is part of the legend: a bounty on mistakes, which is a theory of community dressed as a joke.`,
    tension: `The afterlife argument is about completeness versus time. A cathedral that is never finished can still organize a city; it can also freeze a map that the terrain has left. Some of Knuth's machines and some of his problems feel like a beautiful past. Another tension: literate programming never conquered industry, which prefers speed of change to speed of understanding. The market did not want books that compile. There is also a gentle political question. An art of computer programming can sound like an art for those with leisure to be exact, while the world runs on sloppy systems that nonetheless fly. The atlas keeps him as a standard of care, not as a rebuke to every hacker who shipped.`,
  },

  "neural-networks": {
    lede: `A neural network is a stack of adjustable functions, loosely inspired by brains, that learns by changing its weights. It is now the engine of much [[machine-learning|machine learning]], though the biological metaphor is a ladder that some would like to throw away. In the atlas the concept sits between [[artificial-intelligence|artificial intelligence]], [[neuroscience|neuroscience]], and [[linear-algebra|linear algebra]]. Layers transform representations; depth makes those transformations compose; data supplies the pressure that carves them. The idea is old. The scale is new. The opacity is the bill.`,
    idea: `At bottom a network is composition plus parameters. Each layer is a linear map followed by a nonlinearity; training is the search for parameters that make a loss small on examples and, one hopes, on the world. Backpropagation is just the chain rule organized as an [[algorithms|algorithm]]. What surprised even some of the inventors is how far this impoverished cartoon of a neuron could go once compute and data crossed a threshold: vision, speech, translation, then fluent language. Universal approximation theorems say a wide enough net can mimic many functions; they do not say a training procedure will find the mimic, nor that the mimic will be the function you meant. The relation to real nervous systems is part inspiration, part advertising. Brains are wet, spiking, embodied, and metabolically stingy; these nets are dense matrix multiplies. Still, the concept forces a conversation with [[mind|Mind]]: if intelligence can be a fitted map, what remains of rules, symbols, and the inner theater.`,
    lineage: `McCulloch and Pitts wrote a logical neuron in 1943. Rosenblatt's perceptron learned, then Minsky and Papert mapped its limits, and a winter fell on the idea of layers. Rumelhart, Hinton, Williams, and others revived backpropagation in the 1980s; another winter followed when the method seemed a niche. The 2010s, with GPUs, large sets, and convolutional and later transformer architectures, turned the niche into infrastructure. [[Neuroscience|Neuroscience]] watched with mixed feelings: a cousin succeeding by ignoring most of the family traits. The [[internet|Internet]] provided the examples; industrial labs provided the kilowatts. What is called a revolution is a long, twice-buried research program that finally met a market. [[Von-neumann|Von Neumann]]'s machines, ironically sequential, became the hosts of this massively parallel metaphor.`,
    tension: `The concept cannot yet do what its press release claims: explain itself, guarantee its errors, or know when it is outside its training world. Interpretability, robustness, and data provenance are open. So is the scientific question of whether scaling is a theory or a habit. Another tension is ecological and civic: these systems concentrate compute, harvest human text, and rearrange labor while speaking the language of [[biology|biology]]. The atlas keeps [[ethics|ethics]] and [[consciousness|consciousness]] nearby, not to mystify a matrix multiply, but to prevent a matrix multiply from mystifying us. A reader should be able to admire the engineering without kneeling to the metaphor.`,
  },

  "machine-learning": {
    lede: `Machine learning is the family of [[algorithms|algorithms]] that improve with examples rather than with explicit rules. It is statistics with an appetite, [[linear-algebra|linear algebra]] with a deadline, and a bet that the future will look enough like the past to make fitting worthwhile. In the atlas it neighbors [[artificial-intelligence|artificial intelligence]], [[neural-networks|neural networks]], [[probability|probability]], and even [[protein-folding|protein folding]], because the same wager — let the data speak — now runs through science as well as through products. Generalization is the name of the miracle and of the failure. A model that only remembers has not learned. A model that invents wildly has not learned either.`,
    idea: `The working idea is a loop: choose a hypothesis class, score it on data, search for a better score, and hope the score tracks reality. Supervision, reinforcement, and self-supervision are different ways of obtaining the score. Overfitting is the original sin; regularization, hold-out sets, and Bayesian priors are the penances. [[Probability|Probability]] supplies the language of uncertainty; optimization supplies the muscle; representation supplies the art. [[Neural-networks|Neural networks]] currently dominate the art, but trees, kernels, and linear models remain the right tools in many rooms. The field's philosophical center is induction: how a finite sample licenses a claim about the unsampled. That is [[hume|Hume]]'s problem with a GPU. When learning systems recommend, diagnose, or deny, the statistical loop becomes a civic one, and [[ethics|ethics]] stops being an afterword. The atlas treats machine learning as a concept rather than a magic, so that a reader can see the loss function hiding inside the demo.`,
    lineage: `Least squares is already learning. Twentieth-century statistics, pattern recognition, and cybernetic dreamers all arrived before the brand name. Rosenblatt, Vapnik, Valiant's PAC model, and the connectionist revivals are chapters; so are expert systems that failed by refusing to learn. The [[internet|Internet]] and the digitization of everything turned scarce examples into floods. ImageNet, GPUs, and a culture of leaderboards made [[neural-networks|neural networks]] industrial. Biology and chemistry then discovered that fitted models could see in data what hand-built rules had missed, as in [[protein-folding|protein folding]]. The lineage is not a straight road from perceptron to product. It is a braid of [[mathematics|mathematics]], hardware, and institutions that decided prediction was worth more than explanation, at least for a while.`,
    tension: `What the concept cannot yet do is tell you, reliably, when it is wrong in a new world. Distribution shift, spurious correlations, and adversarial examples are not bugs at the edge; they are the problem of induction wearing work clothes. Another tension: data are not a natural resource. They are traces of people, often taken without a story of consent, which makes [[political-philosophy|political philosophy]] interior to the pipeline. There is a scientific tension too. A model that predicts without a mechanism can be a tool or a postponement of understanding. The atlas keeps [[epistemology|epistemology]] close, because a culture that only rewards loss curves will forget to ask what a curve is allowed to mean.`,
  },

  "quantum-computing": {
    lede: `Quantum computing is computation that rides superposition and interference, promising speedups that are real, rare, and easy to oversell. It is not a faster laptop. It is a different physics of the state, in which amplitudes cancel as well as add. In the atlas the concept binds [[quantum-mechanics|quantum mechanics]] to [[algorithms|algorithms]], [[cryptography|cryptography]], and [[information-theory|information theory]]. A qubit is a delicate resource; decoherence is the tax; error correction is the hoped-for civilization. The subject forces computer science to remember [[physics|physics]], and physics to remember that information is a physical kind.`,
    idea: `A classical bit is a choice; a qubit is a pair of amplitudes whose squared magnitudes are chances. Entanglement makes the joint state richer than a list of parts. Interference lets a well-designed [[algorithms|algorithm]] cancel the amplitudes of wrong answers. Shor's factoring algorithm and Grover's search are the famous exhibits: one a threat to much of public-key [[cryptography|cryptography]], the other a quadratic consolation prize. Most problems do not enjoy a miracle. The complexity map is redrawn, not thrown away; BQP sits on it like a new continent whose coastline is still being surveyed. Hardware is a zoo of trapped ions, superconducting circuits, photons, and spin, all fighting noise. Error-corrected logical qubits are the industrial question. Until they exist at scale, the field is a mixture of theorems, noisy devices, and rhetoric. The atlas files it as a concept because the idea is already working in theory while the machines are still learning to remember.`,
    lineage: `Feynman asked whether a quantum system could be simulated without the exponential tax of classical amplitudes. Deutsch framed a quantum Turing machine. Bernstein, Vazirani, Simon, Shor, and Grover, in the 1990s, turned the frame into algorithms that made governments listen. [[Shannon|Shannon]]'s theory had to be rewritten for quantum channels; Holevo's bound taught that qubits are not a free lunch of bits. Experimental progress crawled, then leapt in small noisy processors that the 2010s named and marketed. The [[cold-war|Cold War]]'s successor funding — intelligence agencies, cloud firms, national labs — recognized that a cryptographically relevant machine would be a historical event. The lineage is thus part [[physics|physics]], part [[computation-theory|computation theory]], part geostrategy. [[Einstein|Einstein]]'s discomfort with entanglement became, by a long irony, an engineering resource.`,
    tension: `The concept cannot yet offer a general acceleration of thought, and the gap between a press release and a logical qubit is where reputations go to soften. Skeptics ask whether error correction will scale before patience runs out; enthusiasts ask whether skeptics are measuring the wrong decade. Cryptographic migration cannot wait for the debate to end, which is a practical tension with a calendar. There is also a conceptual risk: treating quantum as magic rather than as linear algebra with a Born rule. The atlas keeps [[complexity-classes|complexity classes]] and [[information-theory|information theory]] adjacent so that wonder does not get a free pass. A speedup is a theorem or it is a wish.`,
  },

  compilers: {
    lede: `A compiler is a program that turns human-facing code into machine-facing instructions, and sometimes into other human-facing code. It is a translator with opinions: about types, about performance, about what errors deserve to be loud. In the atlas the concept lives inside [[programming-languages|programming languages]], with roots in [[algorithms|algorithms]] and [[computation-theory|the theory of computation]]. Parsing, analysis, optimization, and code generation are its four seasons. To study compilers is to study how one notation can be faithful to another without being identical, which is a problem of [[logic|logic]] as much as of engineering.`,
    idea: `Compilation is a pipeline of representations. A lexer makes characters into tokens; a parser makes tokens into trees; semantic analysis asks whether the tree means; optimizations rewrite the tree or a later graph so that the meaning is cheaper; a backend emits the dialect of a particular machine or virtual machine. Each stage is an [[algorithms|algorithm]] with a contract. Static types are a conversation that happens here, before any user arrives. Optimizers are where the compiler becomes an author, moving code, deleting code, specializing code, sometimes so aggressively that debugging feels like archaeology. Just-in-time compilers blur the line by compiling while the program runs, using the program as its own profile. Interpreters skip the long translation and pay at each step. The concept matters because languages are promises, and a promise that cannot be implemented is a daydream. [[Category-theory|Category theory]] and formal semantics try to say what preservation of meaning even is.`,
    lineage: `Grace Hopper's compilers and Backus's Fortran team in the 1950s had to convince skeptics that a machine translation would not insult the metal. Algol and the theory of grammars, especially Chomsky's hierarchy as computer scientists used it, made parsing a science. Optimizing compilers grew with architectures: registers, pipelines, caches, then many cores. LLVM, gcc, and a fleet of language-specific compilers became infrastructure as ordinary as roads. The [[internet|Internet]] added new targets — bytecode, JavaScript, WebAssembly — so that a compiler is now often a bridge between virtual machines rather than a path to silicon. [[Knuth|Knuth]]'s tools and the culture of literate systems sit nearby: a compiler is a program that must be trusted, which is a special kind of literature.`,
    tension: `What compilers cannot yet do, fully, is prove they have not lied. Bugs in optimizers are rare and legendary; undefined behavior is a treaty written in invisible ink. Formal verification of compilers, as in CompCert, shows the cost of honesty. Another tension is political in a small key: a compiler's warnings and types are a pedagogy, and pedagogies exclude. There is also an economic tension. Languages without good compilers wither; compiler talent is scarce; the metal keeps moving. The atlas keeps [[computation-theory|computation theory]] in the picture because some properties are undecidable, and a compiler that pretends to decide them all is a hazard wearing a helpful face.`,
  },

  "distributed-systems": {
    lede: `A distributed system is computation spread across machines that fail, delay, and disagree, yet must still present a world. There is no shared instant, only messages, clocks that lie, and the hope of [[algorithms|algorithms]] for consensus. In the atlas the concept binds the [[internet|Internet]] to [[databases|databases]] and [[networks|networks]]. The central drama is not speed. It is partial failure: one node dies, another lies, a partition splits the map, and the remaining parts must choose between availability, consistency, and wishful thinking. To design such a system is to practice [[philosophy|philosophy]] with timeouts.`,
    idea: `When there is no common memory, agreement becomes a protocol. Lamport's work on time, Paxos and its descendants, Raft, Byzantine fault tolerance, and the CAP vocabulary are all ways of naming what cannot be had at once. Idempotency, retries, exactly-once illusions, and leader election are the folk crafts. [[Databases|Databases]] at planetary scale are distributed systems whether they advertise it or not; so are blockchains, content-delivery nets, and this atlas if it is ever more than one process. The theory is unforgiving. FLP says consensus is impossible in an asynchronous system with even one silent failure, which is why real systems cheat with timing assumptions. Engineering then becomes the art of cheating safely. [[Information-theory|Information theory]] tells you a channel has capacity; distributed systems tell you the channel has an adversary, a scheduler, and a budget. The user sees a page. Under the page is a parliament of machines.`,
    lineage: `Time-sharing and early networks taught that a computer is not a room. The ARPANET and then the [[internet|Internet]] made partial failure ordinary. Lamport, Lynch, Fischer, and others wrote the theorems that still scare students. Industry learned, expensively, that failover is a behavior, not a checkbox. The 2000s brought large data-center systems, MapReduce, Dynamo, Spanner, and a public conversation about consistency models that used to live in papers. The [[cold-war|Cold War]] origins of packet networks linger as a design taste: route around damage. Cryptocurrencies later made Byzantine agreement a pop culture object, for better and worse. The lineage is a slow acceptance that the unit of computing is no longer the machine. It is the protocol.`,
    tension: `The concept cannot abolish the trade-offs it describes. Anyone who promises global consistency, instant writes, and painless partition-tolerance is selling a story. Another tension is operational: most outages are humans and configs, not theorems, which tempts teams to ignore the theorems until a split-brain event teaches otherwise. There is a civic angle. Distributed systems now host speech, money, and identification; their failure modes are public events. The atlas keeps [[political-philosophy|political philosophy]] nearby because consensus is a political word that computer science borrowed and may have to give back, with interest, when the parliament of machines governs more than pages.`,
  },

  "complexity-classes": {
    lede: `Complexity classes are the taxonomy of difficulty: P, NP, PSPACE, and the rest of the zoo that organizes theoretical computer science. They do not say how to solve a problem. They say what kind of beast the problem is, and which other beasts it can be transformed into. In the atlas the concept sits under [[algorithms|algorithms]] and [[computation-theory|computation theory]], with a long edge into [[cryptography|cryptography]] and [[proof|proof]]. P versus NP is the famous open wound. Around it lives a whole comparative anatomy of time, space, randomness, and interaction.`,
    idea: `A class is a set of languages, which is to say a set of decision problems, defined by the resources a machine may spend. Polynomial time, P, is the usual stand-in for feasible. NP is the class of problems whose yes-answers have short, quickly checkable witnesses. NP-completeness, via Cook, Levin, and Karp, showed that hundreds of natural problems stand or fall together. Reductions are the morphisms of this world: a well-behaved translation that says, if you could do that, you could do this. Randomness, interaction, quantum amplitudes, and approximation each generate further classes — BPP, IP, BQP, APX — a map that is still being drawn. [[Cryptography|Cryptography]] lives on the belief that some problems are hard on average, not only in the worst case, which is a stricter and more delicate hope. The concept is how the field avoids treating every puzzle as a unique weather event. It is comparative anatomy for procedures.`,
    lineage: `Cobham and Edmonds in the 1960s proposed polynomial time as a model of the feasible. Cook's 1971 theorem, Levin's independent work, and Karp's list made NP-completeness a method. Garey and Johnson became a handbook of hardness. The 1970s and 1980s added space classes, the polynomial hierarchy, randomized classes, and the slow, brilliant work that showed IP equals PSPACE. [[Turing|Turing]] had given an infinite horizon; complexity gave a budget. [[Godel|Gödel]] had asked about provability; this field asked about the cost of proof, which is why proof complexity is a neighbor. As machines grew faster, the classes did not dissolve, because they are about growth rates, not about this year's clock. The [[quantum-computing|quantum]] class BQP is a late continent, still only partly explored.`,
    tension: `The concept cannot, yet, tell us whether P equals NP, which means it cannot tell us whether creativity in the sense of finding a witness is essentially harder than checking one. Most theorists bet on inequality; the bet is not a theorem. Another tension: worst-case classes can mis-describe typical instances, which is why average-case complexity and smoothed analysis exist and why practitioners sometimes shrug. Cryptographic hardness needs still another grain. There is a cultural tension too. Hardness results can sound like a stop sign; they are often a request for a different question — approximation, parameterization, randomness. The atlas keeps [[mathematics|mathematics]] and [[algorithms|algorithms]] in the same view so that a class is never mistaken for a verdict on human ingenuity.`,
  },

  databases: {
    lede: `A database is an engineered memory: a way of storing facts so they can be asked questions later, by people who were not there when the facts arrived. It is not a pile of files. It is a contract about shape, identity, concurrency, and loss. In the atlas the concept sits between [[knowledge-representation|knowledge representation]], [[distributed-systems|distributed systems]], [[information-theory|information theory]], and [[algorithms|algorithms]]. Query is the art; consistency is the ethics; scale is the weather. To forget well is part of the design, which is why deletion, provenance, and time are as interesting as insertion.`,
    idea: `Codd's relational model taught that data could be described independently of the accidents of storage, and that a query language could be a [[logic|logic]]. Tables, keys, and joins are a civic language for facts. Transactions — atomicity, consistency, isolation, durability — are a promise that concurrent lives will not corrupt one another's past. Not all useful memories are relational. Documents, graphs, key-value stores, and search indexes optimize different questions, often by relaxing a promise. [[Distributed-systems|Distributed]] databases then discover that the promises fight: you may have to choose among freshness, availability, and partition survival. Indexes are [[algorithms|algorithms]] wearing a civil uniform. Query planners are little compilers. The concept matters to this atlas because an atlas is a queryable memory of ideas, and because [[knowledge-representation|knowledge representation]] without storage is a speech that no one can rerun. Data without a model is a rumor with backups.`,
    lineage: `Business files and punched cards are ancestors. Hierarchical and network databases in the 1960s bound data to a path. Codd in 1970, and the SQL culture that followed, made relations a default. Ingres, System R, Oracle, and later open-source systems turned the model into an industry. The web and then the [[internet|Internet]]'s advertising and logging machines produced stores that valued availability and flexible schema over joins. MapReduce and its descendants treated the file system as a database for people who had given up on one. Spanner and its kin tried to buy global time. Meanwhile academic work on provenance, uncertainty, and datalog kept the [[logic|logic]] alive. The lineage is a long negotiation between the elegance of a model and the violence of a workload.`,
    tension: `What databases cannot yet do is remember people as people would wish to be remembered: accurately, contextually, forgetfully, and under their own control. GDPR-style rights collide with logs, replicas, and machine-learning traces. Another tension is truth. A schema can force a world to be more rectangular than it is; a schemaless store can hide the fact that a world was forced anyway, later, in code. Consistency models are trade-offs that users feel as ghosts: a cart that reappears, a balance that flickers. The atlas keeps [[ethics|ethics]] and [[distributed-systems|distributed systems]] adjacent, because a memory at scale is a political instrument even when it only claims to be a table.`,
  },

  internet: {
    lede: `The Internet is a network of networks, built on packets, protocols, and a bet that best-effort is enough. It has no center, which is both a design and a myth. In the atlas it is a concept rather than a place, tying [[networks|networks]], [[distributed-systems|distributed systems]], [[information-theory|information theory]], [[cryptography|cryptography]], and the [[information-age|Information Age]] into one fabric. Addresses, routing, and layered protocols let unlike systems cooperate without becoming one system. That cooperation is the invention. Everything else — the web, the feeds, the markets — is a city that grew on the road.`,
    idea: `Packets are little letters that find their way, or do not. TCP and IP, the pair most often named, offer a dumb, flexible network and smarter edges, a philosophy as much as a stack. End-to-end arguments say to keep the middle stupid so the ends can innovate; middleboxes then grew anyway, because institutions hate stupid middles. [[Distributed-systems|Distributed systems]] live on top; [[cryptography|cryptography]] tries to make the public path private; [[information-theory|information theory]] explains why the path can be noisy and still useful. Names, from DNS to the web's URLs, are a political resource. So are standards bodies. The Internet is not the web, not social media, not the cloud, though each is a parasite and a fruit. As a [[networks|network]] it shows hubs, long tails, and fragility to certain hits. As a commons it shows enclosure. The atlas treats it as an object of thought, not only as plumbing, because it is the present tense of connection.`,
    lineage: `ARPANET, packet switching, Cerf and Kahn's internetworking, NSFNET, and the privatization of the backbone are the usual stations. The [[cold-war|Cold War]] funded a network that could route around damage; researchers then used it to route around distance. Email, file transfer, and discussion groups preceded the web; Berners-Lee's web made linking ordinary; browsers made it a public square. Mobile radios then put the square in a pocket. [[Shannon|Shannon]] did not design it, but every channel in it lives in his landscape. The [[printing-press|printing press]] is a fair ancestor in spirit: a collapse in the cost of copying that rearranges who may speak. The lineage includes standards wars, commercial capture, and the slow discovery that a best-effort net will carry both science and predation.`,
    tension: `The concept cannot, by itself, guarantee a public sphere. Protocols are neutral only in the way roads are neutral. Surveillance, concentration, and infrastructural power sit in the middle of a system that tells a story about edges. Another tension: global connectivity versus national sovereignty, a fight over names, cables, and filters. Reliability and security were late additions to a design that assumed a small, civil club. The atlas keeps [[democracy|democracy]], [[capitalism|capitalism]], and [[networks|networks]] in view, because the Internet is now a constitution that no one quite voted for. A reader should be able to admire the packets without mistaking them for freedom.`,
  },

  history: {
    lede: `History is the study of what happened, why it seemed inevitable only afterward, and how the dead still act. It is not a warehouse of dates. It is an argument about causes, scales, and voices, conducted with evidence that is always incomplete. As a continent of this atlas it gathers [[ancient-civilizations|ancient civilizations]], the [[renaissance|Renaissance]], the [[scientific-revolution|Scientific Revolution]], the [[enlightenment|Enlightenment]], the [[industrial-revolution|Industrial Revolution]], and the [[world-wars|world wars]]. Time is the climate. Contingency is the weather. The hub exists so that ideas in [[philosophy|philosophy]] and [[computing|computing]] cannot pretend they grew without hunger, empire, and accident.`,
    idea: `A historical claim is a claim about change in a human world, backed by traces: texts, pots, genomes, prices, ruins, songs. The traces never speak once. They are cross-examined. Scale matters. A biography, a city, a sea, a planet — each scale makes different causes look like causes. The Annales taste for structures, the Marxist taste for production, the microhistorian's taste for a miller, the global historian's taste for [[silk-road|connections]]: these are methods, not mere styles. [[Democracy|Democracy]], [[capitalism|capitalism]], and the [[agricultural-revolution|Agricultural Revolution]] are not natural kinds sitting in the past. They are patterns we name in order to compare. History neighbors [[systems|systems]] because feedback and path dependence are historical facts, and neighbors [[biology|biology]] because bodies, plagues, and food are. The atlas insists that a map of knowledge without time is a lie by omission. Every concept has a birthday, even when the birthday is a blur.`,
    lineage: `Peoples have always told origin stories. Herodotus and Thucydides made inquiry a genre; Sima Qian made a bureau of the past; Ibn Khaldun made rise and fall a science of social cohesion. Early modern Europe learned, slowly, to distrust providence as an all-purpose cause. Ranke told historians to show how it actually was, which licensed both rigor and naivete. The nineteenth century nationalized the archive; the twentieth century, after the [[world-wars|world wars]], distrusted the nation as narrator. Social history, women's history, postcolonial history, and environmental history widened who counted as a subject. The [[printing-press|printing press]] and then the [[internet|Internet]] changed what could be compared. This vault inherits that widening. It also inherits the danger: a little history can be an alibi, and a grand narrative can be a weapon.`,
    tension: `The fault line is between the past as it was and the past as it is usable. Every present raids the archive for legitimacy. Another fault: structure versus event, the anonymous process versus the night that could have gone otherwise. A third is the archive itself — who was documented, who was silenced, whose languages survive. Digital abundance now mimics completeness and hides new silences. The atlas does not pick a school. It keeps [[political-philosophy|political philosophy]] and the [[library-of-alexandria|Library of Alexandria]] in view so that a reader feels both the need to know and the ease of losing the knowing. History is a continent of arguments that refuse to stay finished.`,
  },

  "ancient-civilizations": {
    lede: `Ancient civilizations are the first dense experiments in living together at scale: cities, scripts, temples, palaces, and the surplus that made specialists possible. Sumer, Egypt, the Indus, China, Mesoamerica, and their neighbors did not form a single story, yet they rhyme — irrigation and writing, kings and gods, trade and tax. In the atlas the topic grows out of the [[agricultural-revolution|Agricultural Revolution]] and toward the [[axial-age|Axial Age]] and the [[silk-road|Silk Road]]. It is the long morning in which [[philosophy|philosophy]], [[mathematics|mathematics]], and the state learn to be possible. Collapse is part of the lesson, not a sequel.`,
    idea: `Civilization here is a loaded word, and the field now prefers to speak of urban societies, palatial economies, and literate elites without ranking them on a ladder toward us. What they share is storage: of grain, of labor, of names. Writing begins as account and becomes epic. Law becomes a public object. [[Democracy|Democracy]] is a late and local experiment among much older forms of rule. Monumental building is a technology of awe and of work discipline. Long-distance trade, including the ancestors of the [[silk-road|Silk Road]], moves obsidian, tin, textiles, and gods. The [[library-of-alexandria|Library of Alexandria]] is a Hellenistic climax of a much older archival urge. Comparative work across Afro-Eurasia and the Americas guards against the idea that history has one plot. The atlas keeps this topic next to [[networks|networks]] and [[agriculture|farming]] because a city is an ecology with a bureaucracy, and a script is a memory that can outlive a throat.`,
    lineage: `Nineteenth-century archaeology and philology invented "civilization" as a European mirror. Cuneiform, hieroglyphs, oracle bones, and Maya glyphs were cracked on different clocks, each unlocking a voice that had been waiting. Processual archaeology later asked about systems — irrigation, population, energy — while others restored kings and rituals to the center. Genomic and climate evidence now join texts and potsherds, sometimes rudely. The [[enlightenment|Enlightenment]] had already used Egypt and Rome as moral theater; nationalism later grabbed ancestors. Contemporary scholarship tries to hold the marvel and the violence together: slavery, sacrifice, patriarchy, and high art as one complex. This node inherits that effort. It is a topic, not a museum gift shop.`,
    tension: `The open problem is how to compare without ranking, and how to rank causes without pretending the past was a machine. Diffusion versus independent invention still flares, especially where prestige is at stake. Another tension: the written elite versus the silent majority, which archaeology can only partly repair. A third is present politics. Ancient identities are recruited by modern states with a hunger that would impress a Pharaoh. The atlas keeps [[ethics|ethics]] nearby because admiration is not innocence. To study the first cities is to study the invention of inequality as well as of literature, and the two were often the same project.`,
  },

  renaissance: {
    lede: `The Renaissance is a European name for a reopening of classical learning that remade art, politics, and the self, roughly from the fourteenth to the sixteenth century. It was not a sudden light after darkness. It was a movement of humanists, painters, printers, courtiers, and bankers, strongest in Italian cities and then restless across the Alps. In the atlas it neighbors the [[printing-press|printing press]], the [[scientific-revolution|Scientific Revolution]], and [[plato|Plato]], because recovered dialogues and new images arrived together. Perspective, philology, and ambition are its signatures. So are war, plague, and the slave-funded wealth of courts.`,
    idea: `Humanism here means a curriculum and a stance: that eloquence, history, and moral philosophy could form a civic person, and that Greek and Roman texts were partners rather than pagan threats. Artists learned to make space a measurable scene; anatomists looked; engineers drew machines that might almost work. The [[printing-press|printing press]] multiplied the stance until it could not be a coterie. [[Plato|Plato]] returned through Ficino; [[Aristotle|Aristotle]] was already there, wearing scholastic clothes that humanists loved to mock. Courts used spectacle as policy. Republican myths in Florence and Venice fed later [[political-philosophy|political philosophy]], including the long European argument about [[democracy|democracy]] and virtue. The Renaissance is thus both a style and a media event, a new way of being old. It prepared the [[scientific-revolution|Scientific Revolution]] without being identical to it: one still spoke to patrons in myth, the other would learn to speak in numbers to a public.`,
    lineage: `Petrarch's letters to the dead, Brunelleschi's dome, Alberti's treatises, Lorenzo's Florence, papal Rome, Dürer's north, and the wreck of 1527 are the usual beads. Beneath them: the wealth of condottieri and of trade, the Ottoman pressure that sent Greeks and manuscripts west, the recovery of texts that had been safer in Byzantium and in Arabic for centuries. Burckhardt later taught Europe to see a birth of the individual here, a thesis still argued because it flatters. The [[enlightenment|Enlightenment]] would claim the Renaissance as an ancestor; nationalisms would claim its artists as flags. The atlas files the topic as a hinge between [[ancient-civilizations|antiquity]] reused and a modern world that was not yet sure it was modern.`,
    tension: `The word hides as much as it shows. Women, workers, and the colonized appear late in the traditional picture; when they appear, the light looks less kindly. Another tension: rebirth versus continuity. Much that is called medieval was already inventive, and much that is called Renaissance is courtly recycling. There is a geographic tension too. Similar flowerings elsewhere — in Timurid cities, in Ming letters — were not waiting to join this plot. The atlas keeps the [[silk-road|Silk Road]] and [[printing-press|print]] adjacent so that an Italian century cannot pose as the world's only morning. Open problems include how to tell the story without the old ladder of progress, and without throwing away the real shock of the images.`,
  },

  "scientific-revolution": {
    lede: `The Scientific Revolution names a seventeenth-century turn that made nature a book to be read by experiment and [[mathematics|mathematics]]. It is a historians' phrase, contested and indispensable, covering Copernican astronomy, Galilean motion, Newtonian gravitation, new instruments, and new societies that argued in print. In the atlas it binds [[newton|Isaac Newton]] to [[empiricism|empiricism]], [[galileo|Galileo]], the [[enlightenment|Enlightenment]], and [[astronomy|astronomy]]. The claim is not that no one knew anything before. The claim is that the rules for public knowing changed, and that those rules still haunt laboratories, including the ones that built [[computing|computing]].`,
    idea: `What changed was a package: mathematics as the language of motion, experiment as a public witness, instruments as extensions of the senses, and a rhetoric of humility that was also a rhetoric of power. [[Newton|Newton]]'s Principia is a climax, not the whole play; chemistry, anatomy, and natural history had other tempos. [[Empiricism|Empiricism]] and mechanism fought remnants of Aristotelian natures. Royal societies created audiences that could be convinced without a bishop's permission, though kings still paid the bills. The mechanical philosophy imagined a world of matter and motion; [[calculus|calculus]] gave that world a voice. The revolution is as much about trust — who may speak for nature — as about heliocentrism. Later science inherited both the method and the imperial patronage that traveled with it. The atlas keeps this topic next to [[history|history]] and [[physics|physics]] so that a law of nature never looks unborn.`,
    lineage: `Copernicus postponed the ancient sky; Kepler found ellipses; Galileo pointed a tube and wrote in Italian at his enemies. Descartes offered a method and a vortex; Bacon offered an induction and a courtier's plan for organized research. Boyle's air pump became a drama of witnessing. [[Newton|Newton]], in Cambridge and in London, unified motion and gravity, then spent himself on alchemy, scripture, and the Mint. Print culture, including the [[printing-press|printing press]]'s mature world of journals, made replication a social hope. The [[enlightenment|Enlightenment]] packaged the century as reason's victory. Twentieth-century historians — Koyré, Kuhn, Shapin — took the package apart, showing metaphysics, controversy, and gentlemanly trust inside the method. The lineage is an argument about whether there was a revolution at all, or a slow, lumpy reorganization of credibility.`,
    tension: `The open problem is the name. Revolution implies rupture; many practices were continuous, and similar curiosities existed in other literate cultures. Another tension: mathematics versus experience, a quarrel [[hume|Hume]] and [[kant|Kant]] would inherit. A third is political. A method that disenchants nature can enchant empire, because a world of resources is a world that can be measured and taken. Gender and exclusion are not side notes; they shaped who counted as a witness. The atlas leaves the reader between admiration for the instruments and suspicion of the story that only Europe woke up. [[Biology|Biology]] and [[computing|computing]] still live inside that story's grammar.`,
  },

  enlightenment: {
    lede: `The Enlightenment was a wager that public reason could improve institutions, knowledge, and lives, concentrated in the long eighteenth century and never confined to Paris. It was a party of [[philosophy|philosophy]], print, salons, and reform, with [[kant|Immanuel Kant]] and [[hume|David Hume]] among its sharpest minds, and with slavery and empire among its hypocrisies. In the atlas the topic ties [[scientific-revolution|the Scientific Revolution]] to [[democracy|democracy]] and [[political-philosophy|political philosophy]]. Encyclopedias, coffeehouses, and letters were its [[networks|networks]]. The wager is still open, which is why the word is used as both compliment and insult.`,
    idea: `Public reason, here, means that claims should be able to travel without a coat of office: that a reader, in principle, could follow. That ideal produced critiques of miracle, of absolute monarchy, of clerical monopoly, and of cruelty that had been called custom. It also produced a faith in improvement that could be naive about power. [[Hume|Hume]] unmasked causation and the self as habits; [[Kant|Kant]] answered by relocating the conditions of knowledge into the structure of mind, and by insisting that persons are ends. Encyclopedists tried to map the arts and trades; this [[knowledge-atlas|Knowledge Atlas]] is, in one mood, their descendant. [[Democracy|Democracy]] and human rights are political fruits with bitter seeds, because many Enlightenments excluded women, the poor, and the colonized from the public that reason was supposed to serve. The topic is therefore not a doctrine. It is a set of tools and a set of alibis, still in use.`,
    lineage: `The [[scientific-revolution|Scientific Revolution]] supplied a method and a prestige. Print, including newspapers and the [[printing-press|press]]'s cheap grandchildren, supplied a public. Spinoza, Locke, Voltaire, Rousseau, Smith, and the Scots made different Enlightenments — radical, moderate, commercial, sentimental. Revolutions in America and France claimed the warrant and then taught the world how bloody a warrant can be. Kant's essay on enlightenment, with its motto of daring to know, became a business card for the age. The nineteenth century inherited reform, secularization, and racism dressed as science. Critics from the beginning, including romantics and the enslaved who seized the language of rights, showed the wager's cracks. The atlas files the topic as a climate that still weathers [[ethics|ethics]] and the [[information-age|Information Age]], whenever someone claims that more knowledge will automatically civilize.`,
    tension: `The live fight is whether the Enlightenment is a unfinished emancipation or a mask for domination. Both readings have archives. Instrumental reason can disenchant a forest and call it timber; it can also unmask a tyrant. Another tension: universalism versus plurality. A reason that speaks for everyone may silence those who do not sound like its first speakers. A third is historical: there was no single Enlightenment, and the French story should not eat the others. The atlas keeps [[hume|Hume]]'s skepticism next to [[kant|Kant]]'s hope on purpose. A reader should leave able to use the tools without kneeling to the statues, and able to criticize the statues without throwing away the tools.`,
  },

  "industrial-revolution": {
    lede: `The Industrial Revolution was a shift in the metabolism of societies: fossil energy, factory production, and a new tempo of capital, first concentrated in Britain and then contagious. It rebuilt landscapes, families, clocks, and empires. In the atlas it connects [[capitalism|capitalism]], [[thermodynamics|thermodynamics]], [[lovelace|Ada Lovelace]], and the later [[information-age|Information Age]]. Coal and steam are the famous engines; cotton, iron, and enslaved or coerced labor are the less conveniently famous ones. The topic is not only machines. It is a reorganization of time, so that work could be synchronized like a mechanism.`,
    idea: `What was revolutionary was not a single invention but a coupling: energy density, mechanized production, wage labor, and markets that could reinvest. Factories disciplined bodies; railroads disciplined distance; telegraphs began to discipline news. [[Capitalism|Capitalism]] found a new gear. [[Thermodynamics|Thermodynamics]] was born, in part, from the study of engines that leaked and pushed, a science of limits grown from industrial hunger. Urbanization made new miseries and new publics. The world was knitted into commodity chains that made a mill town depend on a plantation and a mine. [[Lovelace|Lovelace]] and Babbage imagined automating calculation inside this world of looms and mills, which is why [[computing|computing]] has an industrial ancestry as well as a logical one. The environmental bill — carbon, extinction, slag — was posted late and is still being paid. The atlas treats the topic as a hinge between early modern craft and a planet that now runs on stored sunlight and on data.`,
    lineage: `Historians argue about dates, usually centering 1760–1840 in Britain, with Belgium, New England, the Rhineland, and Japan on other clocks. Enclosures, colonial markets, and financial instruments prepared the ground. Cotton connects Lancashire to the American South and to India; that connection is not a sidebar. Steam, then electricity, then oil restaged the play. Socialists, romantics, and reformers wrote the moral literature; engineers wrote the patents. The [[world-wars|world wars]] would later industrialize killing, a sequel already latent in the coupling of science and production. The [[information-age|Information Age]] likes to call itself post-industrial while still burning the older fuels and still disciplining time. The lineage is a set of takeoffs that never quite landed.`,
    tension: `The quarrel is whether this was liberation from Malthusian traps or a new trap with better gadgets. Living standards eventually rose for many; the path there was hungry, smoky, and often coerced. Another quarrel: Britain as miracle versus Britain as extractor, which is an argument about [[capitalism|capitalism]] and empire. A third is ecological. A growth curve drawn on a finite biosphere is a problem the nineteenth century named only in pieces. The atlas keeps [[ecology|ecology]] and [[ethics|ethics]] in the neighborhood so that a reader can admire a locomotive without calling it destiny. Open questions include how to narrate industrialization outside Europe without making Europe the only plot, and how to think a future that must unlearn this metabolism without a fairy-tale return.`,
  },

  "world-wars": {
    lede: `The world wars of the twentieth century were industrial slaughters that redrew maps, accelerated science, and taught a planet fear at a new scale. 1914–1918 and 1939–1945 were not repeats of the same war, yet they form one topic because they industrialized death, mobilized whole economies, and left institutions — the UN, nuclear weapons, decolonization's timetable — that still bind the present. In the atlas they neighbor the [[cold-war|Cold War]], [[turing|Alan Turing]], [[einstein|Albert Einstein]], and the [[information-age|Information Age]]. Total war is the grim name. No later peace has been simply a return.`,
    idea: `What made these wars world wars was the coupling of nation, industry, and logistics: railways, oil, chemicals, radios, and then aircraft and rockets. Civilians became targets and workers in the same breath. Propaganda became a science of [[attention|attention]]. Genocide, especially the Holocaust, is not a subplot; it is a revelation of what a modern state can do with files, trains, and ideology. Science was drafted. [[Turing|Turing]]'s ciphers, [[einstein|Einstein]]'s letter, radar, penicillin at scale, and the bomb are not decorations on a military history. They are the military history of knowledge. Empires cracked; women entered and were asked to leave workplaces; refugees redrew cities. The wars also globalized American power and Soviet power, setting the board for the [[cold-war|Cold War]]. The atlas keeps this topic inside [[history|history]] rather than inside a game of generals, because the causes include [[capitalism|capitalism]], nationalism, and humiliation, not only a gunshot in Sarajevo or a dictator's will.`,
    lineage: `The long nineteenth century's alliances, arms races, and imperial rivalries loaded the spring. The first war's stalemate and starving winters produced revolutions and a bitter peace. Fascism and Stalinism are children of that bitterness as well as of their own ideologies. The second war's theaters spanned from the Atlantic to the Pacific, with China and the colonial world as central, not peripheral. Aftermaths included Nuremberg, Bretton Woods, partition, and a human-rights language that the [[enlightenment|Enlightenment]] had drafted and the camps made urgent. Memory itself became a battleground: monuments, denials, museums. [[Computing|Computing]] and nuclear [[physics|physics]] left the wars as peacetime giants. The lineage is still unfinished wherever veterans' grandchildren argue about flags.`,
    tension: `The open wounds are moral and narrative. Can one explain without explaining away? Can one compare without ranking sufferings? National stories still fight to be the main plot. Another tension: technology as neutral tool versus technology as accomplice, a question that [[ethics|ethics]] and [[computing|computing]] still inherit. A third is scale. World war can flatten regions into a single word and lose the particular street. The atlas keeps [[political-philosophy|political philosophy]] nearby because legitimacy, emergency, and the right to kill are philosophical problems that these years made ordinary. A reader should leave unable to treat 1914–1945 as a movie and unable to treat the present as unrelated.`,
  },

  "library-of-alexandria": {
    lede: `The Library of Alexandria is the emblem of collected knowledge — and of how easily a civilization's memory can burn. The Museion's stacks, under the Ptolemies, tried to hold Greek learning and much else in a port that faced the Mediterranean and the Nile. In the atlas the concept binds [[ancient-civilizations|ancient civilizations]] to the [[knowledge-atlas|Knowledge Atlas]] and to the [[printing-press|printing press]], because every later archive both imitates and fears this story. The fires, plural and partly legendary, matter less as a police report than as a parable: accumulation is not the same as survival.`,
    idea: `A great library is a theory of the world disguised as furniture. Alexandria's project was Hellenistic and royal: gather, copy, edit, monopolize, display. Scholars made catalogs, editions, and arguments; ships were said to be searched for books. The working idea is that knowledge can be centralized, corrected, and made to serve a court and a cosmos at once. That idea never dies. It reappears in monasteries, in early modern encyclopedias, in national libraries, in data centers, and in this vault. Loss is interior to the idea, because a center is a target and a single copy is a bet against time. The parable is used to scold Christians, Muslims, pagans, and neglect itself, which is a sign that we are dealing with a myth of meaning as well as with archaeology. [[Knowledge-representation|Knowledge representation]] begins, in one mood, as a librarian's problem: how to find what you gathered before the gathering becomes a second wilderness.`,
    lineage: `Founded in the third century BCE in a Greek-Macedonian dynasty ruling Egypt, the Library and Museion sat in a city of many languages. Callimachus's pinakes are a ghost of a catalog. Later centuries saw decline, possibly several destructions, and a long afterlife in which every culture explained the loss as the other culture's sin. Renaissance humanists used the story to urge gathering; the [[printing-press|printing press]] changed the odds by multiplying copies; the [[internet|Internet]] changed them again by multiplying copies that can vanish together if the protocols fail. Alexandria is thus less an address than a recurring dream of completeness. The [[knowledge-atlas|Knowledge Atlas]] inherits the dream and the fear, preferring a graph of copies and links to a single sacred stack.`,
    tension: `What the concept cannot do is tell a clean true story of the fire, because the sources are late and motivated. That uncertainty is useful. It warns against treating any archive as innocent. Another tension: completeness versus curation. A library that holds everything holds garbage and treasure under the same roof, and someone still decides the catalog. Imperial gathering is not the same as sharing. The atlas keeps [[ethics|ethics]] and [[cartography-of-knowledge|cartography of knowledge]] nearby so that a reader can want a universal library without wanting a universal king. The wound of Alexandria is not only that texts vanished. It is that we still believe a building could have saved us.`,
  },

  "printing-press": {
    lede: `The printing press, especially movable type in fifteenth-century Europe, collapsed the cost of copying and therefore changed who could argue. Gutenberg's workshop is the emblem; East Asian print cultures are a reminder that Europe was not the only home of the idea. In the atlas the concept links the [[renaissance|Renaissance]], the [[enlightenment|Enlightenment]], [[information-theory|information theory]], and the [[internet|Internet]]. Replication is the revolution. Once a text can be multiplied faster than a censor can ride, a new public becomes possible, and so does a new kind of error, rumor, and standard.`,
    idea: `A press is a machine for identicality. Manuscript culture produced variance as a matter of course; print produced editions, errata, and the fantasy of a stable page. That stability made science, law, and scripture into objects that distant strangers could point at together. It also made propaganda industrial. The working idea is not "books exist." It is that the marginal cost of a copy falls until argument can be a mass phenomenon. Luther is unthinkable as a European event without print; so are newspapers, novels, and the [[enlightenment|Enlightenment]]'s republic of letters. [[Information-theory|Information theory]] would later measure channels; print is an early channel that carries its own code: typefaces, signatures, privileges, piracy. Compared with the [[internet|Internet]], print is slow and durable; compared with a scribe, it is a flood. The atlas treats the press as a media revolution whose political children include both [[democracy|democracy]] and the pamphlet war.`,
    lineage: `Woodblock printing in East Asia is centuries older than Mainz. Movable metal type in Korea precedes Gutenberg; Europe's contribution was a combination of type, press, paper, and a market of Latin-reading clerks that exploded. The [[renaissance|Renaissance]] rode the machine; the Reformation weaponized it; early modern states tried to license it. Scientific journals in the seventeenth century made print a witness. Cheap print in the nineteenth made mass literacy a political fact. Radio, television, and then networks did not abolish the press; they inherited its problems of copy, authority, and flood. The lineage is a series of cheapenings, each of which looks like liberation from the previous gatekeeper and then grows gatekeepers of its own.`,
    tension: `Print cannot, by itself, enlighten. It can standardize error and multiply hatred as easily as tables of logarithms. Another tension: the author as owner versus the copy as commons, a fight that copyright law still referees and that digital networks have made feral. A third is geographic. To tell the story only as Gutenberg is to miss a world of print. The atlas keeps the [[library-of-alexandria|Library of Alexandria]] and the [[internet|Internet]] as bookends so that a reader sees accumulation, multiplication, and link as three different answers to the same fear of forgetting. Open questions include how a public survives when copies are infinite and attention is not.`,
  },

  "silk-road": {
    lede: `The Silk Road was never one road. It was a changing web of overland and maritime routes that moved silk, spices, metals, horses, religions, technologies, and plague across Afro-Eurasia. In the atlas the concept sits between [[ancient-civilizations|ancient civilizations]], [[networks|networks]], and [[history|history]], a reminder that globalization is not a recent invention. Caravanserais and ports were its packets; empires were sometimes its protocols. To study it is to study connection without romance: profit, devotion, diplomacy, and contagion traveling together in the same saddlebag.`,
    idea: `As a [[networks|network]] the Silk Road is a lesson in hubs and long links. Oasis cities and entrepôts — Chang'an, Samarkand, Palmyra, later Malacca — mattered more than the famous empty miles. Goods were not the only payloads. Buddhism, Islam, Nestorian Christianity, and manichaean scriptures moved; so did paper, stirrups, and strains of Yersinia. The working idea for this atlas is that culture is not a set of bounded pearls but a traffic. [[Information-cascade|Cascades]] along such routes can be religious or epidemiological. States tried to tax and protect the traffic; when they failed, the traffic rerouted, which is the same wisdom later claimed by the [[internet|Internet]]. Maritime silk routes often carried more than the deserts. Naming the whole web "silk" is a later convenience, a luxury good standing in for a system. The system is the subject.`,
    lineage: `Han missions westward, Parthian and Kushan middle grounds, Tang cosmopolitanism, Islamic caliphates, Mongol peace and Mongol terror, Venetian and Genoese appetites, Ming maritime ventures: the stations change, the pattern of relay persists. Nineteenth-century geographers, notably Richthofen, coined the phrase and folded it into imperial dreams of Central Asia. Recent scholarship has restored the many actors who were not Europe-bound: Sogdian traders, Uighur scribes, Swahili ports. The [[cold-war|Cold War]] split the old routes with new borders; contemporary belt-and-road politics try to inherit the brand. The lineage is thus half archaeology, half branding. The atlas prefers the archaeology, and the [[networks|network]] mathematics that makes the archaeology speak.`,
    tension: `The concept cannot bear the weight of being a parable of peace. Trade did not abolish conquest; sometimes it paid for it. Another tension: overland myth versus maritime volume, and silk versus the uglier cargos, including enslaved people. A third is present politics. Modern states recruit the Silk Road as destiny, which is a way of laundering pipelines and influence. The atlas keeps [[capitalism|capitalism]] and [[ancient-civilizations|ancient civilizations]] both in view so that a reader can see an old web without calling it innocent or calling it a preview of a corporation. Connection is a fact. Virtue is a separate claim.`,
  },

  "axial-age": {
    lede: `The Axial Age is Karl Jaspers' name for the middle-first-millennium BCE bloom of [[philosophy|philosophy]], prophecy, and ethics across several Old World societies. In a few centuries, in places not then a single world, one finds the Buddha, the Upanishadic sages, Confucius and the Daoist critics, the Hebrew prophets, and the Greek philosophers from the Ionians through [[plato|Plato]]. In the atlas the concept links [[ancient-civilizations|ancient civilizations]] to [[ethics|ethics]] and [[philosophy|philosophy]]. It is a risky comparative idea: powerful if it names a real synchrony, misleading if it becomes a club of the spiritually mature.`,
    idea: `Jaspers' wager was that a new kind of interiority and universality appeared: a break with merely local gods and palatial cults toward questions of the good, the real, and the right that a person might ask against the city. [[Plato|Plato]]'s forms, prophetic justice, Buddhist unbinding, Confucian repair of ritual — these are not the same answer, but they may be the same pitch of question. The working idea is second-order: thought turning on custom, and [[ethics|ethics]] becoming a matter of teaching rather than only of blood. Critics note the exclusions — Mesoamerica, much of Africa, women as authors — and the stretch of dates. Still, as a mapmaking tool the Axial Age helps this atlas explain why [[philosophy|philosophy]] can have several birthplaces without a single capital. It is a concept about the conditions under which a critic can appear inside a civilization and be heard.`,
    lineage: `The phrase is mid-twentieth-century, born from Jaspers' attempt to think a world after the [[world-wars|world wars]] without making Europe the measure. He gathered older comparative work and gave it a dramatic name. Weber's sociology of religions, and later scholarship on the "age of criticism," are cousins. Archaeologists and philologists keep moving the furniture: dating the Upanishads, rereading Confucius, asking whether Greek uniqueness was a trick of survival of texts. The [[enlightenment|Enlightenment]] had already made Greece a secular origin; Jaspers tried to decenter that origin without flattening differences. The atlas inherits the decentering and the caution. [[Aristotle|Aristotle]] and the Buddha do not become one sage just because they rhyme on a timeline.`,
    tension: `The concept cannot prove that the synchrony is more than coincidence plus our love of patterns. Trade and empire connected some of these zones, not all, and not equally. Another tension: spiritualization as a story that slights political economy — iron, coinage, cities — as the real solvents of old orders. A third is moral. Axial can become a compliment paid to texts that survived, while oral and popular religions look "pre-axial" by archival accident. The atlas keeps [[history|history]] and [[ethics|ethics]] in argument here. Use the name as a hypothesis about a worldwide climate of criticism. Do not use it as a passport office for civilizations.`,
  },

  "cold-war": {
    lede: `The Cold War was a forty-year standoff, roughly 1947–1991, that wired the planet, funded science, and split the sky without quite becoming a third world war between its principals. Nuclear weapons made direct battle between the United States and the Soviet Union a kind of suicide, so the conflict moved into proxies, spies, sports, space, and ideology. In the atlas it grows out of the [[world-wars|world wars]] and into the [[internet|Internet]], [[game-theory|game theory]], and the [[information-age|Information Age]]. Bipolar is the schematic. The schematic always leaked.`,
    idea: `Deterrence is a psychological technology: make the other believe that catastrophe is automatic. [[Game-theory|Game theory]], some of it from [[von-neumann|von Neumann]]'s world, supplied a language of credibility, first strike, and mutually assured destruction that statesmen mixed with improvisation. Alliances, coups, and development aid were instruments. So were universities. Much of postwar [[physics|physics]], area studies, and early [[computing|computing]] grew in this greenhouse, including packet networks designed to route around damage. Decolonization unfolded inside the same weather: new states courted, overthrown, or ignored. Culture was a front — jazz, socialist realism, kitchens, Olympics. The working idea for this atlas is that a peace can be a war conducted by other infrastructures. The planet's cables, satellites, and research budgets still show the grain.`,
    lineage: `Yalta, Hiroshima, Fulton, Berlin, Korea, Cuba, Vietnam, Afghanistan, and the year 1989 are the beads of a Western rosary; other rosaries add Bandung, Prague, Chile, Angola. The arms race produced both existential risk and civilian spinoffs. The space race produced a Moon and a way of seeing Earth whole. Détente, then a second coldness, then a sudden Soviet collapse that surprised its winners. Archives opened unevenly. Historians now write a global Cold War rather than a merely transatlantic one, restoring the Third World's hot wars to the center. The [[internet|Internet]]'s ancestry in ARPA is one of the era's ironies: a military net that became a civilian commons, then a market. The lineage did not end so much as change temperature.`,
    tension: `The concept cannot decide whether nuclear peace was a triumph of reason or a decades-long luck. Another tension: treating the conflict as ideological (freedom versus socialism) versus treating it as imperial rivalry in new clothes. Both are partly true; either, alone, is propaganda. A third is memory. Nostalgia for bipolar clarity forgets the corpses in proxy theaters. The atlas keeps [[ethics|ethics]] and [[capitalism|capitalism]] adjacent, and [[democracy|democracy]] too, because each camp's self-story was a weapon. A reader should be able to hold the research university and the mushroom cloud in one thought, which is how this climate actually felt.`,
  },

  "information-age": {
    lede: `The Information Age is the present tense of [[history|history]], in which information becomes the cheap, volatile, organizing stuff of economies, states, and selves. It is a successor story to the [[industrial-revolution|Industrial Revolution]], sometimes too eager to declare industry over while still burning its fuels. In the atlas the concept gathers the [[internet|Internet]], [[computing|computing]], and the [[knowledge-atlas|Knowledge Atlas]] itself. Chips, protocols, and platforms are the visible machines. Attention, data, and logistics are the hidden ones. To live now is to live among copies that move faster than judgments.`,
    idea: `The working idea is that control of flows — of bits, of claims, of coordinates — rivals control of land and factories as a source of power. That does not make atoms obsolete. It makes them addressable. [[Computing|Computing]] supplies the procedures; the [[internet|Internet]] supplies the commons and the mall; [[cryptography|cryptography]] supplies the locks that sometimes hold. Media that were separate — post, press, telephone, television — collapse into one programmable channel. Work becomes partly the management of messages. Politics becomes partly the management of feeds. [[Shannon|Shannon]]'s indifferent bits meet [[capitalism|capitalism]]'s hungry markets and [[democracy|democracy]]'s need for a public, a meeting that is not a peace treaty. This atlas is an artifact of the age: a bet that navigation can be wiser than the feed, that a graph of ideas can resist a stream of stimuli. Whether that bet is pastoral or practical is an open historical question.`,
    lineage: `Telegraphs already shrank the planet; radio and television made simultaneity a mass feeling. Postwar electronics, the transistor, and [[cold-war|Cold War]] research made digital cheap. Personal computers, then the web, then mobile broadband, then machine-learning platforms, each claimed to be the real arrival. Bell's post-industrial prophecy, Castells' network society, and a thousand business books tried to name the turn while it was turning. The [[printing-press|printing press]] is the deep ancestor; the difference is speed, searchability, and surveillance. Environmental and labor histories insist that server farms and mines are as "informational" as apps. The lineage is therefore not a clean exit from industry. It is industry plus a new nervous system.`,
    tension: `The age cannot, yet, tell whether abundance of signal produces knowledge or a new illiteracy of the overwhelmed. Another tension: connection versus capture. A network that can host a commons can host a monopoly, and often does. A third is political. Authoritarian and liberal states have both learned to live inside the same protocols, which should chasten anyone who thinks packets equal freedom. The atlas keeps [[ethics|ethics]] and [[networks|networks]] in view so that a reader can refuse both cyber-utopia and cyber-doom. History is still happening. The information is not an atmosphere we watch. It is a set of decisions about who may remember, charge, and forget.`,
  },

  democracy: {
    lede: `Democracy is government by the many, always incomplete, always argued, never merely a machine. The word names both an Athenian experiment and a modern family of representative, liberal, and radical forms that would have puzzled Pericles. In the atlas it is a concept at the border of [[political-philosophy|political philosophy]], the [[enlightenment|Enlightenment]], [[social-psychology|social psychology]], and [[ancient-civilizations|ancient civilizations]]. Elections are one instrument. They are not the whole idea. The idea is that legitimacy flows upward from those who must live under the rules, and that this flow can be organized without becoming a fiction.`,
    idea: `The working tension inside the concept is between the people as a body and the people as a quarrel. Majority rule without rights can eat minorities; rights without rule can freeze into oligarchy. Representation is a technology for scale, and like all technologies it distorts: parties, districts, money, media. [[Ancient-civilizations|Athens]] mixed lot, assembly, and slavery; modern democracies mix ballots, bureaucracies, and markets. The [[enlightenment|Enlightenment]] supplied a language of rights; social movements supplied the pressure that extended the franchise beyond the gentlemen who wrote the pamphlets. [[Collective-intelligence|Collective intelligence]] is a hopeful cousin: the many can know what the few cannot, if the institutions do not stupidify them. [[Networks|Networks]] now scramble the public, which is why the [[internet|Internet]] is an interior problem for democracy, not an external tool. The atlas treats democracy as a practice that must be redesigned as scales change, not as a trophy won in 1945.`,
    lineage: `The Greek word meant a particular, slave-holding, male, direct form. It was not an ancient compliment everywhere; [[plato|Plato]] distrusted it, and many republics preferred mixed constitutions. Early modern revolutions revived the people as a sovereign, often while limiting who counted. The nineteenth and twentieth centuries made mass democracy thinkable through parties, unions, literacy, and the horrors that made the alternative look worse. Decolonization multiplied republics; some remained democratic, many did not. After the [[cold-war|Cold War]] a brief triumphalism treated liberal democracy as the end of the story. The [[information-age|Information Age]] then discovered that feeds can unmake a public as easily as they inform it. The lineage is a set of enlargements and backslidings, not a staircase.`,
    tension: `The concept cannot settle how much economic equality a political equality requires, which is why [[capitalism|capitalism]] is its most intimate neighbor and rival. Another tension: expertise versus participation, the committee of scientists versus the assembly, newly sharp in an age of [[machine-learning|machine learning]] and of plague. A third is the boundary of the people — nation, resident, world — which climate and migration make urgent. The atlas keeps [[ethics|ethics]] and [[political-philosophy|political philosophy]] in the same climate so that a reader can love self-government without confusing it with a brand. Democracy is a claim that must be made true again, on purpose, against its own oligarchic weather.`,
  },

  capitalism: {
    lede: `Capitalism is an economic order organized around private capital, markets, and the perpetual reinvestment of surplus. It is not identical with trade, which is ancient, nor with greed, which is not a system. In the atlas the concept binds the [[industrial-revolution|Industrial Revolution]] to [[game-theory|game theory]], [[political-philosophy|political philosophy]], and [[networks|networks]]. Prices coordinate strangers; firms command insides; states write the rules that make both possible. Growth is the blessing and the compulsion. To study capitalism is to study a historical creature, not a law of nature that was waiting under the soil.`,
    idea: `The working idea is that production is steered by the search for returns on capital, with labor power bought as a commodity and with competition disciplining (and sometimes devouring) firms. Markets discover information that no planner holds entire, a point that neighbors [[information-theory|information]] and [[hayek|Hayek]] without ending the argument. Property, contract, and credit are legal technologies; without them "the market" is a bazaar. [[Industrial-revolution|Industrial]] capitalism added fossil energy and the factory clock; later forms added the corporation, the welfare compromise, the global supply chain, and the platform. [[Game-theory|Game theory]] models strategic interdependence; it does not by itself justify the game. Finance multiplies claims on the future. The system's dynamism is real: it invents, cheapens, and spreads. So is its restlessness: it cannot easily stop at enough. The atlas keeps [[ecology|ecology]] nearby because a compulsion to grow will meet a biosphere that does not share the compulsion.`,
    lineage: `Agrarian markets and long-distance merchants are prehistory. Early modern Europe, Atlantic slavery, and colonial extraction built a world market in which capital could become self-expanding on a new scale. Smith analyzed commercial society; Marx named the creature and its crises; Weber tied it to a spirit and a bureaucracy. The [[industrial-revolution|Industrial Revolution]] was a metamorphosis, not a birth from nothing. Twentieth-century variants — social democratic, coordinated, neoliberal, state-capitalist — show that capitalism is a family, not a single genome. The [[cold-war|Cold War]] made it an identity as well as an economy. The [[information-age|Information Age]] financialized and platformized it, turning attention and data into terrains of accumulation. The lineage is still being written wherever a city is remade as an asset.`,
    tension: `The concept cannot decide, from inside economics alone, whether this order is the least bad coordination device or a slow catastrophe with excellent gadgets. Inequality, crisis, and ecological overshoot are not accidental stains; whether they are curable without killing the dynamism is the political question. Another tension: freedom of exchange versus the unfreedom of those with only their labor to sell. A third is democracy. Capital can fund a public or enclose it. The atlas keeps [[democracy|democracy]] and [[ethics|ethics]] as arguments, not as decorations. Readers should be able to use the word without reciting a hymn or a curse. It is a system with a history, which means it can end or change, which is why the fights are so loud.`,
  },

  "agricultural-revolution": {
    lede: `The Agricultural Revolution, in the Neolithic sense, is the turn to farming that made surplus, settlement, and specialists possible. It is among the most consequential events that were not an event: a scattered set of domestications, over millennia, in the Fertile Crescent, China, the Americas, and other hearths. In the atlas the concept underlies [[ancient-civilizations|ancient civilizations]], [[ecology|ecology]], and [[history|history]] itself as a study of states. Bread and rice are political facts. So are teeth, plagues, and the inequality that a storehouse invites. Foragers did not vanish from the story. They were pushed to its margins and its myths.`,
    idea: `Domestication is a two-way capture. Plants and animals change; so do humans, in bone, in labor, in ritual. Sedentism can precede farming and farming can fail; the old cartoon of a sudden inspired sower is gone. What remains is a ratchet. Stored calories support non-fishers and non-hunters: priests, soldiers, potters, scribes. Those specialists invent the city and the tax. [[Ecology|Ecology]] records the bill: simplified landscapes, zoonotic disease, soil exhaustion, and also the astonishing productivity that now feeds billions. [[Biodiversity|Biodiversity]] shrinks in the field and sometimes grows in the garden. The working idea for this atlas is that knowledge cultures rest on metabolic regimes. A library needs farmers, even when it does not mention them. [[Biology|Biology]] and [[history|history]] meet here without metaphor. The later British "agricultural revolution" of enclosures and clover is a different, smaller rhyme: another intensification with social winners and losers.`,
    lineage: `Gordon Childe named a Neolithic Revolution; later archaeology softened the revolution into a mosaic of experiments, collapses, and spreads. Göbekli Tepe complicated the sequence of temple and farm. Rice, maize, potato, and millet have their own geographies, which wreck any single Fertile Crescent plot. States from Sumer onward are unthinkable without granaries. Colonial botanists then dragged crops across oceans, a second agricultural revolution that remade diets and empires. The Green Revolution of the twentieth century added fertilizers, dwarf grains, and a new political economy of yield. Each intensification looks, from inside, like salvation from hunger, and from outside, like a narrowing of the possible. The lineage is still open in seed banks, patents, and climate-stressed fields.`,
    tension: `The concept cannot tell us whether farming was a trap or a ladder, a question Scott and others have made sharp: why would free foragers accept the dentist and the taxman? Another tension: progress narratives that treat agriculture as destiny versus romantic narratives that treat it as a fall. Both skip the local, the reversible, the mixed economies that lasted centuries. A third is the present. Industrial farming feeds the [[industrial-revolution|Industrial]] world's descendant and unravels the ecology it requires. The atlas keeps [[ethics|ethics]] and [[ancient-civilizations|ancient civilizations]] in view so that a reader can taste bread as a historical artifact. Surplus made [[philosophy|philosophy]] possible. It also made kings possible. The two arrivals were not a coincidence.`,
  },
};
